--
-- Name: fill_student_meal_waste_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fill_student_meal_waste_columns() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.waste_weight := NEW.left_weight;
  IF NEW.take_weight IS NULL OR NEW.take_weight = 0 THEN
    NEW.waste_rate := 0;
  ELSE
    NEW.waste_rate := ROUND((NEW.left_weight / NEW.take_weight) * 100, 2);
  END IF;
  NEW.meal_date := NEW.meal_time::DATE;
  NEW.week_code := TO_CHAR(NEW.meal_time, 'IYYYIW');
  NEW.month_code := TO_CHAR(NEW.meal_time, 'YYYYMM');
  NEW.year_code := TO_CHAR(NEW.meal_time, 'YYYY');
  NEW.carbon_emission := ROUND((NEW.take_weight - NEW.left_weight) * 0.0025, 2);
  IF TG_OP = 'INSERT' THEN
    NEW.create_time := COALESCE(NEW.create_time, CURRENT_TIMESTAMP);
    NEW.update_time := COALESCE(NEW.update_time, CURRENT_TIMESTAMP);
  ELSE
    NEW.update_time := CURRENT_TIMESTAMP;
  END IF;
  RETURN NEW;
END;
$$;


