INSERT INTO public.student_reward_item (reward_id, reward_name, reward_desc, points_cost, image_url, stock, status, sort_order, create_time, update_time) VALUES (1, '宿舍优先报修券', '可优先处理一次宿舍报修申请。', 88, 'https://images.unsplash.com/photo-1517048676732-d65bc937f952?auto=format&fit=crop&w=600&q=80', 8, 1, 60, '2026-04-20 20:01:13.345985', '2026-04-20 20:01:13.345985');
